 out.append(dict(screening_unit_id=uid,decision='KEEP',confidence='high',primary_spho_domains=dom,required_physics=phy,decision_reason=reason,external_physics_if_any='',format=fmt,page_start=1,page_end=np,visual_inspection_used=1,solution_used=sol,boundary_status='content_boundary_verified',needs_second_review=focus,evidence=f'APhO 2024 file {fid}: all {np} physical statement pages read in full SHA-cached text and all rendered pages actually inspected, including every internal part, equation, graph and apparatus image. One complete top-level parent per source. Quasar solution 983 all nine pages read; pp3/6/7/9 rendered for method/units/source-quality checks.'))
