 c.execute("update paper_boundary_audit set status='full_paper_boundaries_verified',observed_units=1,evidence=?,checked_at=? where file_id=?",(f'All {np} physical pages inspected, beginning through final part. One independently headed {fmt} task; internal A/B/etc and answer-option items remain subparts, no omitted top-level question.',w.now(),fid))
